{"content": "// Game state and core types
export interface GameState {
  isPlaying: boolean;
  isPaused: boolean;
  currentTime: number;
  score: { player1: number; player2: number };
  combo: { player1: number; player2: number };
  accuracy: { player1: number; player2: number };
  currentSong?: Song;
  difficulty: Difficulty;
  gameMode: 'story' | 'multiplayer' | 'practice';
}

// Player types
export type Player = 'player1' | 'player2';

export interface PlayerConfig {
  id: Player;
  name: string;
  keys: {
    left: string;
    down: string;
    up: string;
    right: string;
  };
  color: string;
  position: 'left' | 'right';
}

// Arrow and gameplay types
export type ArrowDirection = 'left' | 'down' | 'up' | 'right';

export interface Arrow {
  id: string;
  direction: ArrowDirection;
  time: number; // When the arrow should be hit (in milliseconds)
  lane: number; // 0-3 for each direction
  player: Player;
  position: [number, number, number]; // 3D position
  speed: number;
  hit: boolean;
  missed: boolean;
}

export type HitResult = 'PERFECT' | 'GREAT' | 'GOOD' | 'MISS';

export interface HitData {
  result: HitResult;
  timeDiff: number;
  arrow: Arrow;
  player: Player;
}

// Song and beatmap types
export interface Song {
  id: string;
  title: string;
  artist: string;
  genre: string;
  bpm: number;
  duration: number; // in seconds
  audioFile: string;
  backgroundImage?: string;
  difficulties: {
    beginner?: BeatMap;
    standard?: BeatMap;
    heavy?: BeatMap;
    challenge?: BeatMap;
  };
}

export interface BeatMap {
  difficulty: Difficulty;
  level: number;
  totalNotes: number;
  arrows: BeatMapArrow[];
}

export interface BeatMapArrow {
  time: number; // Time in milliseconds when arrow should be hit
  direction: ArrowDirection;
  player: Player;
}

export type Difficulty = 'beginner' | 'standard' | 'heavy' | 'challenge';

// Scoring system
export interface ScoreData {
  perfect: number;
  great: number;
  good: number;
  miss: number;
  maxCombo: number;
  totalScore: number;
  accuracy: number;
}

// Game settings
export interface GameSettings {
  scrollSpeed: number;
  audioOffset: number;
  soundEffects: boolean;
  backgroundEffects: boolean;
  player1Keys: PlayerConfig['keys'];
  player2Keys: PlayerConfig['keys'];
}

// Story mode types
export interface StoryScene {
  id: string;
  title: string;
  description: string;
  dialogue: DialogueLine[];
  backgroundImage: string;
  backgroundMusic?: string;
  nextScene?: string;
  choices?: StoryChoice[];
}

export interface DialogueLine {
  character: string;
  text: string;
  avatar?: string;
  emotion?: string;
}

export interface StoryChoice {
  text: string;
  nextScene: string;
  requirement?: {
    type: 'score' | 'accuracy' | 'combo';
    value: number;
  };
}

// Venezuelan Tuki culture and backstory types
export interface Character {
  id: string;
  name: string;
  description: string;
  avatar: string;
  hometown: string;
  favoriteStyle: string;
  backstory: string;
}

export interface TukiStyle {
  name: string;
  description: string;
  characteristics: string[];
  bpmRange: [number, number];
  difficulty: Difficulty;
}", "filePath": "/Users/rais/Desktop/tuki-tuki/src/types/GameTypes.ts"}

{"content": "import { create } from 'zustand';
import { GameState, PlayerConfig, Song, Arrow, HitData, HitResult, GameSettings } from '../types/GameTypes';

// Default player configurations
const defaultPlayer1: PlayerConfig = {
  id: 'player1',
  name: 'Player 1',
  keys: {
    left: 'a',
    down: 's',
    up: 'w',
    right: 'd'
  },
  color: '#FF6B6B',
  position: 'left'
};

const defaultPlayer2: PlayerConfig = {
  id: 'player2',
  name: 'Player 2',
  keys: {
    left: 'ArrowLeft',
    down: 'ArrowDown',
    up: 'ArrowUp',
    right: 'ArrowRight'
  },
  color: '#4ECDC4',
  position: 'right'
};

// Default game settings
const defaultSettings: GameSettings = {
  scrollSpeed: 1.0,
  audioOffset: 0,
  soundEffects: true,
  backgroundEffects: true,
  player1Keys: defaultPlayer1.keys,
  player2Keys: defaultPlayer2.keys
};

interface GameStore {
  // Game state
  gameState: GameState;
  players: [PlayerConfig, PlayerConfig];
  arrows: Arrow[];
  settings: GameSettings;

  // UI state
  currentScene: string;
  showStory: boolean;
  showSettings: boolean;
  isMultiplayer: boolean;

  // Audio state
  audioContext: AudioContext | null;
  currentAudio: HTMLAudioElement | null;

  // Actions
  setGameState: (state: Partial<GameState>) => void;
  setCurrentScene: (scene: string) => void;
  setMultiplayer: (enabled: boolean) => void;
  setPlayer: (playerIndex: 0 | 1, config: Partial<PlayerConfig>) => void;
  setSettings: (settings: Partial<GameSettings>) => void;

  // Game actions
  startGame: (song: Song, isMultiplayer: boolean) => void;
  pauseGame: () => void;
  resumeGame: () => void;
  stopGame: () => void;

  // Arrow management
  addArrow: (arrow: Arrow) => void;
  updateArrows: (deltaTime: number) => void;
  removeArrow: (arrowId: string) => void;

  // Hit detection and scoring
  registerHit: (player: 'player1' | 'player2', direction: string, time: number) => HitResult;
  updateScore: (hitData: HitData) => void;

  // Audio management
  initAudio: () => void;
  playAudio: (audioFile: string) => void;
  stopAudio: () => void;

  // Story mode
  toggleStory: () => void;
  toggleSettings: () => void;
}

export const useGameStore = create<GameStore>((set, get) => ({
  // Initial state
  gameState: {
    isPlaying: false,
    isPaused: false,
    currentTime: 0,
    score: { player1: 0, player2: 0 },
    combo: { player1: 0, player2: 0 },
    accuracy: { player1: 100, player2: 100 },
    difficulty: 'standard',
    gameMode: 'story'
  },

  players: [defaultPlayer1, defaultPlayer2],
  arrows: [],
  settings: defaultSettings,

  currentScene: 'opening',
  showStory: true,
  showSettings: false,
  isMultiplayer: false,

  audioContext: null,
  currentAudio: null,

  // Actions
  setGameState: (state) => set((prev) => ({
    gameState: { ...prev.gameState, ...state }
  })),

  setCurrentScene: (scene) => set({ currentScene: scene }),

  setMultiplayer: (enabled) => set({ isMultiplayer: enabled }),

  setPlayer: (playerIndex, config) => set((prev) => {
    const newPlayers = [...prev.players] as [PlayerConfig, PlayerConfig];
    newPlayers[playerIndex] = { ...newPlayers[playerIndex], ...config };
    return { players: newPlayers };
  }),

  setSettings: (newSettings) => set((prev) => ({
    settings: { ...prev.settings, ...newSettings }
  })),

  // Game actions
  startGame: (song, isMultiplayer) => set((prev) => ({
    gameState: {
      ...prev.gameState,
      isPlaying: true,
      isPaused: false,
      currentTime: 0,
      currentSong: song,
      gameMode: isMultiplayer ? 'multiplayer' : 'story',
      score: { player1: 0, player2: 0 },
      combo: { player1: 0, player2: 0 },
      accuracy: { player1: 100, player2: 100 }
    },
    isMultiplayer,
    arrows: [],
    showStory: false
  })),

  pauseGame: () => set((prev) => ({
    gameState: { ...prev.gameState, isPaused: true }
  })),

  resumeGame: () => set((prev) => ({
    gameState: { ...prev.gameState, isPaused: false }
  })),

  stopGame: () => set((prev) => ({
    gameState: {
      ...prev.gameState,
      isPlaying: false,
      isPaused: false,
      currentTime: 0
    },
    arrows: []
  })),

  // Arrow management
  addArrow: (arrow) => set((prev) => ({
    arrows: [...prev.arrows, arrow]
  })),

  updateArrows: (deltaTime) => set((prev) => {
    const { settings } = prev;
    const updatedArrows = prev.arrows
      .map(arrow => ({
        ...arrow,
        position: [
          arrow.position[0],
          arrow.position[1],
          arrow.position[2] + (settings.scrollSpeed * deltaTime * 0.01)
        ] as [number, number, number]
      }))
      .filter(arrow => arrow.position[2] < 10 && !arrow.hit && !arrow.missed);

    return { arrows: updatedArrows };
  }),

  removeArrow: (arrowId) => set((prev) => ({
    arrows: prev.arrows.filter(arrow => arrow.id !== arrowId)
  })),

  // Hit detection and scoring
  registerHit: (player, direction, time) => {
    const { arrows, gameState } = get();
    const playerArrows = arrows.filter(arrow => 
      arrow.player === player && 
      arrow.direction === direction as any && 
      !arrow.hit && 
      !arrow.missed &&
      Math.abs(arrow.position[2]) < 2 // Hit zone
    );

    if (playerArrows.length === 0) return 'MISS';

    // Find closest arrow
    const closestArrow = playerArrows.reduce((closest, current) => 
      Math.abs(current.position[2]) < Math.abs(closest.position[2]) ? current : closest
    );

    const timeDiff = Math.abs(closestArrow.position[2]);
    let result: HitResult = 'MISS';

    if (timeDiff <= 0.3) result = 'PERFECT';
    else if (timeDiff <= 0.6) result = 'GREAT';
    else if (timeDiff <= 1.0) result = 'GOOD';
    else result = 'MISS';

    // Mark arrow as hit
    set((prev) => ({
      arrows: prev.arrows.map(arrow => 
        arrow.id === closestArrow.id ? { ...arrow, hit: true } : arrow
      )
    }));

    // Update score
    const hitData: HitData = {
      result,
      timeDiff,
      arrow: closestArrow,
      player
    };

    get().updateScore(hitData);

    return result;
  },

  updateScore: (hitData) => set((prev) => {
    const { result, player } = hitData;
    const scoreValues = {
      'PERFECT': 100,
      'GREAT': 80,
      'GOOD': 50,
      'MISS': 0
    };

    const newCombo = result === 'MISS' ? 0 : prev.gameState.combo[player] + 1;
    const comboMultiplier = Math.min(newCombo / 10, 3);
    const points = scoreValues[result] * (1 + comboMultiplier);

    return {
      gameState: {
        ...prev.gameState,
        score: {
          ...prev.gameState.score,
          [player]: prev.gameState.score[player] + points
        },
        combo: {
          ...prev.gameState.combo,
          [player]: newCombo
        }
      }
    };
  }),

  // Audio management
  initAudio: () => {
    if (typeof window !== 'undefined' && !get().audioContext) {
      const context = new (window.AudioContext || (window as any).webkitAudioContext)();
      set({ audioContext: context });
    }
  },

  playAudio: (audioFile) => {
    const { currentAudio } = get();
    if (currentAudio) {
      currentAudio.pause();
      currentAudio.currentTime = 0;
    }

    const audio = new Audio(audioFile);
    audio.play().catch(console.error);
    set({ currentAudio: audio });
  },

  stopAudio: () => {
    const { currentAudio } = get();
    if (currentAudio) {
      currentAudio.pause();
      currentAudio.currentTime = 0;
      set({ currentAudio: null });
    }
  },

  // UI actions
  toggleStory: () => set((prev) => ({ showStory: !prev.showStory })),
  toggleSettings: () => set((prev) => ({ showSettings: !prev.showSettings }))
}));", "filePath": "/Users/rais/Desktop/tuki-tuki/src/store/gameStore.ts"}

{"content": "import React from 'react';
import { Canvas } from '@react-three/fiber';
import { useGameStore } from './store/gameStore';
import StoryScreen from './components/ui/StoryScreen';
import GameScreen from './components/game/GameScreen';
import SettingsPanel from './components/ui/SettingsPanel';
import './App.css';

function App() {
  const { 
    showStory, 
    showSettings, 
    gameState, 
    currentScene,
    initAudio 
  } = useGameStore();

  // Initialize audio context on first user interaction
  React.useEffect(() => {
    const handleUserInteraction = () => {
      initAudio();
      document.removeEventListener('click', handleUserInteraction);
      document.removeEventListener('keydown', handleUserInteraction);
    };

    document.addEventListener('click', handleUserInteraction);
    document.addEventListener('keydown', handleUserInteraction);

    return () => {
      document.removeEventListener('click', handleUserInteraction);
      document.removeEventListener('keydown', handleUserInteraction);
    };
  }, [initAudio]);

  return (
    <div className="app">
      {/* Background Canvas for 3D elements */}
      <div className="canvas-container">
        <Canvas
          camera={{ 
            position: [0, 0, 8], 
            fov: 75 
          }}
          dpr={[1, 2]}
          gl={{ 
            antialias: true,
            alpha: true,
            powerPreference: 'high-performance'
          }}
        >
          <ambientLight intensity={0.4} />
          <pointLight position={[10, 10, 10]} intensity={1} />
          <pointLight position={[-10, -10, -10]} intensity={0.5} color="#4ECDC4" />

          {/* 3D Game Scene */}
          {gameState.isPlaying && <GameScreen />}
        </Canvas>
      </div>

      {/* UI Overlays */}
      <div className="ui-overlay">
        {/* Story/Menu Screen */}
        {showStory && (
          <StoryScreen scene={currentScene} />
        )}

        {/* Settings Panel */}
        {showSettings && (
          <SettingsPanel />
        )}

        {/* Game HUD */}
        {gameState.isPlaying && !showStory && !showSettings && (
          <div className="game-hud">
            <div className="score-display">
              <div className="player-score player1">
                <h3>Player 1</h3>
                <div className="score">{gameState.score.player1.toLocaleString()}</div>
                <div className="combo">Combo: {gameState.combo.player1}</div>
                <div className="accuracy">Accuracy: {gameState.accuracy.player1.toFixed(1)}%</div>
              </div>

              <div className="song-info">
                <h2>{gameState.currentSong?.title || 'Tuki Tuki'}</h2>
                <p>{gameState.currentSong?.artist || 'Venezuelan Rhythm'}</p>
                <div className="difficulty">{gameState.difficulty.toUpperCase()}</div>
              </div>

              <div className="player-score player2">
                <h3>Player 2</h3>
                <div className="score">{gameState.score.player2.toLocaleString()}</div>
                <div className="combo">Combo: {gameState.combo.player2}</div>
                <div className="accuracy">Accuracy: {gameState.accuracy.player2.toFixed(1)}%</div>
              </div>
            </div>
          </div>
        )}

        {/* Venezuelan flag accent */}
        <div className="venezuelan-accent">
          <div className="flag-stripe yellow"></div>
          <div className="flag-stripe blue"></div>
          <div className="flag-stripe red"></div>
        </div>
      </div>

      {/* Audio element for background music */}
      <audio id="background-audio" loop />
    </div>
  );
}

export default App;", "filePath": "/Users/rais/Desktop/tuki-tuki/src/App.tsx"}

{"content": "/* Venezuelan-inspired color palette */
:root {
  --venezuela-yellow: #FCDD09;
  --venezuela-blue: #CF142B;
  --venezuela-red: #00247D;
  --neon-pink: #FF6B6B;
  --neon-blue: #4ECDC4;
  --neon-purple: #A8E6CF;
  --dark-bg: #1a1a2e;
  --darker-bg: #16213e;
  --darkest-bg: #0f3460;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Arial', 'Helvetica', sans-serif;
  background: linear-gradient(135deg, var(--dark-bg), var(--darker-bg), var(--darkest-bg));
  color: white;
  overflow: hidden;
  height: 100vh;
}

.app {
  width: 100vw;
  height: 100vh;
  position: relative;
  overflow: hidden;
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.ui-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 10;
  pointer-events: none;
}

.ui-overlay > * {
  pointer-events: auto;
}

/* Venezuelan flag accent */
.venezuelan-accent {
  position: absolute;
  top: 0;
  right: 0;
  width: 100px;
  height: 100vh;
  display: flex;
  flex-direction: column;
  opacity: 0.3;
  pointer-events: none;
  z-index: 5;
}

.flag-stripe {
  flex: 1;
  width: 100%;
}

.flag-stripe.yellow {
  background: var(--venezuela-yellow);
}

.flag-stripe.blue {
  background: var(--venezuela-blue);
}

.flag-stripe.red {
  background: var(--venezuela-red);
}

/* Game HUD */
.game-hud {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.score-display {
  position: absolute;
  top: 20px;
  left: 0;
  right: 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 0 40px;
  z-index: 15;
}

.player-score {
  background: rgba(0, 0, 0, 0.7);
  border-radius: 15px;
  padding: 20px;
  backdrop-filter: blur(10px);
  border: 2px solid;
  text-align: center;
  min-width: 200px;
}

.player-score.player1 {
  border-color: var(--neon-pink);
  box-shadow: 0 0 20px rgba(255, 107, 107, 0.3);
}

.player-score.player2 {
  border-color: var(--neon-blue);
  box-shadow: 0 0 20px rgba(78, 205, 196, 0.3);
}

.player-score h3 {
  font-size: 1.2rem;
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.player-score .score {
  font-size: 2rem;
  font-weight: bold;
  margin-bottom: 5px;
}

.player-score .combo,
.player-score .accuracy {
  font-size: 0.9rem;
  opacity: 0.8;
  margin-bottom: 3px;
}

.song-info {
  background: rgba(0, 0, 0, 0.8);
  border-radius: 15px;
  padding: 20px;
  text-align: center;
  backdrop-filter: blur(10px);
  border: 2px solid var(--venezuela-yellow);
  box-shadow: 0 0 30px rgba(252, 221, 9, 0.4);
}

.song-info h2 {
  font-size: 1.8rem;
  margin-bottom: 5px;
  color: var(--venezuela-yellow);
  text-shadow: 0 0 10px rgba(252, 221, 9, 0.5);
}

.song-info p {
  font-size: 1rem;
  opacity: 0.8;
  margin-bottom: 10px;
}

.song-info .difficulty {
  background: var(--venezuela-yellow);
  color: var(--dark-bg);
  padding: 5px 15px;
  border-radius: 20px;
  font-weight: bold;
  font-size: 0.8rem;
  letter-spacing: 1px;
}

/* Story Screen Styles */
.story-screen {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.9);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  z-index: 20;
}

.story-content {
  max-width: 800px;
  text-align: center;
  padding: 40px;
  background: rgba(26, 26, 46, 0.95);
  border-radius: 20px;
  border: 2px solid var(--venezuela-yellow);
  box-shadow: 0 0 40px rgba(252, 221, 9, 0.3);
}

.story-title {
  font-size: 3rem;
  color: var(--venezuela-yellow);
  margin-bottom: 20px;
  text-shadow: 0 0 20px rgba(252, 221, 9, 0.5);
  font-weight: bold;
}

.story-text {
  font-size: 1.2rem;
  line-height: 1.6;
  margin-bottom: 30px;
  opacity: 0.9;
}

.story-choices {
  display: flex;
  gap: 20px;
  justify-content: center;
  flex-wrap: wrap;
}

.story-button {
  background: linear-gradient(45deg, var(--neon-pink), var(--neon-blue));
  border: none;
  padding: 15px 30px;
  border-radius: 25px;
  color: white;
  font-weight: bold;
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.3s ease;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.story-button:hover {
  transform: translateY(-3px);
  box-shadow: 0 5px 20px rgba(255, 107, 107, 0.4);
}

.story-button:active {
  transform: translateY(0);
}

/* Character dialogue */
.dialogue-container {
  margin: 30px 0;
  text-align: left;
}

.dialogue-line {
  background: rgba(0, 0, 0, 0.6);
  padding: 15px 20px;
  margin: 10px 0;
  border-radius: 15px;
  border-left: 4px solid var(--neon-blue);
}

.dialogue-character {
  font-weight: bold;
  color: var(--neon-blue);
  font-size: 1.1rem;
  margin-bottom: 5px;
}

.dialogue-text {
  font-size: 1rem;
  line-height: 1.5;
}

/* Settings Panel */
.settings-panel {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: rgba(26, 26, 46, 0.95);
  border-radius: 20px;
  padding: 40px;
  border: 2px solid var(--neon-purple);
